#!/usr/bin/env python3
"""Write assets/typing.svg: the README's typing line, as a self-contained animated SVG.

Each line is typed out character by character, held, then replaced by the next, in a loop (SMIL).
Inter is embedded from assets/fonts so the line looks the same everywhere; when fontTools is
installed it is cut down to the characters used. Characters Inter lacks (the Chinese line) use
the system's CJK font.

    python3 .github/scripts/typing_svg.py            # rewrite assets/typing.svg
"""
import base64
import io
import os
import xml.etree.ElementTree as ET
from html import escape

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
FONT = os.path.join(ROOT, "assets", "fonts", "inter-latin-wght-normal.woff2")
OUT = os.path.join(ROOT, "assets", "typing.svg")

LINES = [
    "College Student @ Rutgers",
    "Finance + Computer Science",
    "Tinkering with Arduino & AI tools",
    "罗格斯在读 · 金融 + 计算机",
]
WIDTH, HEIGHT, SIZE, WEIGHT, COLOR = 760, 48, 22, 500, "#00F3FF"
TYPE_S, PAUSE_S = 3.2, 1.2     # time to type a line, then how long it stays


def font_data():
    raw = open(FONT, "rb").read()
    try:
        from fontTools import subset
        from fontTools.ttLib import TTFont
    except ImportError:
        return raw
    font = TTFont(io.BytesIO(raw))
    options = subset.Options()
    options.flavor = "woff2"
    options.layout_features = ["kern", "liga", "calt"]
    sub = subset.Subsetter(options)
    sub.populate(text="".join(LINES))
    sub.subset(font)
    out = io.BytesIO()
    font.flavor = "woff2"
    font.save(out)
    return out.getvalue()


def main():
    cycle = TYPE_S + PAUSE_S
    total = cycle * len(LINES)
    texts = []
    for n, line in enumerate(LINES):
        start, end = n * cycle, n * cycle + cycle
        chars = list(line)
        spans = []
        for i, ch in enumerate(chars):
            shown = start + 0.05 + TYPE_S * i / len(chars)
            spans.append(
                f'<tspan opacity="0">{escape(ch)}'
                f'<set attributeName="opacity" to="1" begin="loop.begin+{shown:.3f}s"/>'
                f'<set attributeName="opacity" to="0" begin="loop.begin+{end:.3f}s"/></tspan>')
        texts.append(f'<text x="{WIDTH / 2:g}" y="{HEIGHT / 2:g}" text-anchor="middle" dominant-baseline="central" '
                     f'xml:space="preserve">{"".join(spans)}</text>')
    b64 = base64.b64encode(font_data()).decode()
    alt = " · ".join(LINES)
    svg = f"""<svg xmlns="http://www.w3.org/2000/svg" width="{WIDTH}" height="{HEIGHT}" viewBox="0 0 {WIDTH} {HEIGHT}" role="img" aria-label="{escape(alt)}">
<!-- Generated by .github/scripts/typing_svg.py. Inter: SIL Open Font License, see assets/fonts/LICENSE.md -->
<style>
  @font-face {{ font-family: 'Inter Typing'; src: url(data:font/woff2;base64,{b64}) format('woff2'); font-weight: 100 900; }}
  text {{ font-family: 'Inter Typing', 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', 'Noto Sans CJK SC', sans-serif;
         font-size: {SIZE}px; font-weight: {WEIGHT}; fill: {COLOR}; }}
</style>
<rect width="0" height="0"><animate id="loop" attributeName="x" values="0;0" dur="{total:.3f}s" begin="0s;loop.end"/></rect>
{chr(10).join(texts)}
</svg>
"""
    ET.fromstring(svg)
    with open(OUT, "w") as f:
        f.write(svg)
    print(f"wrote {os.path.relpath(OUT, ROOT)} ({len(svg)} bytes)")


if __name__ == "__main__":
    main()
